<?php
require __DIR__ . '/../app/bootstrap.php';
$u=require_role(['owner','admin','manager','staff']); $msg=null; $newKey=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $a=$_POST['action']??'';
 if($a==='provider' && can('provider.manage',$u)){ $s=$db->prepare('INSERT INTO provider_accounts(provider_type,provider_name,account_email,account_label,internal_notes) VALUES(?,?,?,?,?)');$s->execute([$_POST['provider_type']?:'MANUAL_PARTNER',trim($_POST['provider_name']),trim($_POST['account_email'])?:null,trim($_POST['account_label'])?:null,trim($_POST['internal_notes'])?:null]);audit('provider_created','provider_accounts',(int)$db->lastInsertId());$msg='Provider added.'; }
 if($a==='reseller' && can('reseller.manage',$u)){ $name=trim($_POST['name']);$email=trim($_POST['email']);$pw=$_POST['password'];if(strlen($pw)>=10){$db->beginTransaction();$s=$db->prepare('INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,"reseller","active")');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$uid=(int)$db->lastInsertId();$s=$db->prepare('INSERT INTO resellers(user_id,name,email) VALUES(?,?,?)');$s->execute([$uid,$name,$email]);$rid=(int)$db->lastInsertId();$db->commit();audit('reseller_created','resellers',$rid);$msg='Reseller created.';}}
 if($a==='license' && can('license.manage',$u)){ $s=$db->prepare('INSERT INTO licenses(provider_account_id,license_key,domain,reseller_id,status,purchase_date,cost,expires_at) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$_POST['provider_account_id']!==''?(int)$_POST['provider_account_id']:null,trim($_POST['license_key']),trim($_POST['domain'])?:null,$_POST['reseller_id']!==''?(int)$_POST['reseller_id']:null,$_POST['status']?:'available',$_POST['purchase_date']?:null,$_POST['cost']!==''?$_POST['cost']:null,$_POST['expires_at']?:null]);$id=(int)$db->lastInsertId();audit('license_created','licenses',$id);$msg='License added.';}
 if($a==='reissue' && can('reissue.manage',$u)){ $id=(int)$_POST['id'];$status=$_POST['status'];$note=trim($_POST['admin_note']);$s=$db->prepare('SELECT rr.*,l.license_key,r.name reseller_name FROM reissue_requests rr JOIN licenses l ON l.id=rr.license_id JOIN resellers r ON r.id=rr.reseller_id WHERE rr.id=?');$s->execute([$id]);$rr=$s->fetch();if($rr){$db->beginTransaction();$db->prepare('UPDATE reissue_requests SET status=?,handled_by=?,admin_note=? WHERE id=?')->execute([$status,$u['id'],$note?:null,$id]);if($status==='completed'){$db->prepare('UPDATE licenses SET domain=?,status="active" WHERE id=?')->execute([$rr['new_domain'],$rr['license_id']]);$db->prepare('INSERT INTO license_history(license_id,user_id,action,old_domain,new_domain,notes) VALUES(?,?,?,?,?,?)')->execute([$rr['license_id'],$u['id'],'reissue_completed',$rr['current_domain'],$rr['new_domain'],$note?:null]);}$db->commit();audit('reissue_'.$status,'reissue_requests',$id);telegram_notify("📌 <b>REISSUE UPDATED</b>\nReseller: ".e($rr['reseller_name'])."\nLicense: ".e($rr['license_key'])."\nStatus: ".e(strtoupper($status)));$msg='Reissue updated.';}}
 if($a==='api_key' && can('api.manage',$u)){ $rid=(int)$_POST['reseller_id'];$plain='skynoc_'.bin2hex(random_bytes(24));$s=$db->prepare('INSERT INTO api_keys(reseller_id,name,key_prefix,key_hash,expires_at) VALUES(?,?,?,?,?)');$s->execute([$rid,trim($_POST['name'])?:'API Key',substr($plain,0,15),hash('sha256',$plain),$_POST['expires_at']?:null]);$newKey=$plain;audit('api_key_created','api_keys',(int)$db->lastInsertId());}
 if($a==='telegram' && $u['role']==='owner'){ $s=$db->prepare('INSERT INTO telegram_settings(id,bot_token,admin_chat_id) VALUES(1,?,?) ON DUPLICATE KEY UPDATE bot_token=VALUES(bot_token),admin_chat_id=VALUES(admin_chat_id)');$s->execute([trim($_POST['bot_token']),trim($_POST['admin_chat_id'])]);$msg='Telegram settings saved.';}
}
$providers=$db->query('SELECT id,provider_name,account_email,account_label,status FROM provider_accounts ORDER BY id DESC')->fetchAll();
$resellers=$db->query('SELECT id,name,email,status FROM resellers ORDER BY id DESC')->fetchAll();
$licenses=$db->query('SELECT l.*,r.name reseller_name,p.provider_name FROM licenses l LEFT JOIN resellers r ON r.id=l.reseller_id LEFT JOIN provider_accounts p ON p.id=l.provider_account_id ORDER BY l.id DESC LIMIT 100')->fetchAll();
$reissues=$db->query('SELECT rr.*,l.license_key,r.name reseller_name FROM reissue_requests rr JOIN licenses l ON l.id=rr.license_id JOIN resellers r ON r.id=rr.reseller_id ORDER BY rr.id DESC LIMIT 50')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SkyNoc Admin</title><style>*{box-sizing:border-box}body{font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;margin:0;background:#f6f8fb;color:#0f172a}.nav{background:#111827;color:#fff;padding:15px 5%;display:flex;justify-content:space-between;align-items:center;gap:15px}.nav a{color:#fff}.wrap{max-width:1250px;margin:24px auto;padding:0 16px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:16px}.card{background:#fff;padding:20px;border-radius:16px;box-shadow:0 4px 20px #0f172a0a;border:1px solid #e5e7eb}input,select,textarea,button{width:100%;box-sizing:border-box;padding:12px;margin:5px 0 9px;border:1px solid #dbe2ea;border-radius:10px;font:inherit}button{background:#111827;color:#fff;border:0;font-weight:700}table{width:100%;min-width:760px;border-collapse:collapse;background:#fff;margin-bottom:24px}td,th{padding:12px;border-bottom:1px solid #eef2f7;text-align:left;font-size:13px}.table-wrap{overflow-x:auto;border-radius:14px;margin-bottom:24px}.msg{background:#ecfdf5;color:#166534;padding:12px;border-radius:10px;margin-bottom:15px}.secret{background:#fffbeb;color:#92400e;padding:14px;border-radius:10px;word-break:break-all}@media(max-width:700px){.nav{align-items:flex-start;flex-direction:column}.wrap{padding:0 12px}.card{padding:16px}h1{font-size:28px}}</head><body><div class="nav"><b>SkyNoc Admin</b> · <?=e($u['name'])?> (<?=e($u['role'])?>) · <a href="/dashboard">Dashboard</a> · <a href="/logout">Logout</a></div><div class="wrap"><h1>Management</h1><?php if($msg):?><div class="msg"><?=e($msg)?></div><?php endif;?><?php if($newKey):?><div class="secret"><b>New API key — copy now. It will not be shown again:</b><br><?=e($newKey)?></div><?php endif;?><div class="grid">
<?php if(can('provider.manage',$u)):?><div class="card"><h3>Add Provider</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="provider"><input name="provider_name" placeholder="Provider name" required><input name="account_email" type="email" placeholder="Upstream account email"><input name="account_label" placeholder="Internal label"><select name="provider_type"><option>MANUAL_PARTNER</option><option>WHMCS_API</option></select><textarea name="internal_notes" placeholder="Internal notes"></textarea><button>Add Provider</button></form></div><?php endif;?>
<?php if(can('reseller.manage',$u)):?><div class="card"><h3>Create Reseller</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="reseller"><input name="name" placeholder="Reseller name" required><input name="email" type="email" placeholder="Login email" required><input name="password" type="password" placeholder="Temporary password (10+ chars)" required><button>Create Reseller</button></form></div><?php endif;?>
<?php if(can('license.manage',$u)):?><div class="card"><h3>Add License</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="license"><input name="license_key" placeholder="License key" required><input name="domain" placeholder="Domain"><select name="provider_account_id"><option value="">Provider</option><?php foreach($providers as $p):?><option value="<?=$p['id']?>"><?=e($p['provider_name'].' — '.$p['account_label'])?></option><?php endforeach;?></select><select name="reseller_id"><option value="">Unassigned</option><?php foreach($resellers as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select><select name="status"><option>available</option><option>active</option><option>suspended</option></select><input name="purchase_date" type="date"><input name="cost" type="number" step="0.01" placeholder="Cost"><input name="expires_at" type="datetime-local"><button>Add License</button></form></div><?php endif;?>
<?php if(can('api.manage',$u)):?><div class="card"><h3>Create API Key</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="api_key"><select name="reseller_id" required><?php foreach($resellers as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select><input name="name" placeholder="Key name"><input name="expires_at" type="datetime-local"><button>Generate API Key</button></form></div><?php endif;?>
<?php if($u['role']==='owner'):?><div class="card"><h3>Telegram</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="telegram"><input name="bot_token" placeholder="Bot token" required><input name="admin_chat_id" placeholder="Admin chat ID" required><button>Save Telegram</button></form></div><?php endif;?>
</div><h2>Licenses</h2><div class="table-wrap"><table><tr><th>ID</th><th>License</th><th>Domain</th><th>Provider</th><th>Reseller</th><th>Status</th></tr><?php foreach($licenses as $l):?><tr><td><?=$l['id']?></td><td><?=e($l['license_key'])?></td><td><?=e($l['domain'])?></td><td><?=e($l['provider_name'])?></td><td><?=e($l['reseller_name'])?></td><td><?=e($l['status'])?></td></tr><?php endforeach;?></table></div>
<h2>Reissue Requests</h2><div class="table-wrap"><table><tr><th>ID</th><th>License</th><th>Reseller</th><th>Current → New</th><th>Status</th><th>Action</th></tr><?php foreach($reissues as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['license_key'])?></td><td><?=e($r['reseller_name'])?></td><td><?=e($r['current_domain'])?> → <?=e($r['new_domain'])?></td><td><?=e($r['status'])?></td><td><?php if(can('reissue.manage',$u)):?><form method="post" style="min-width:180px"><?=csrf_field()?><input type="hidden" name="action" value="reissue"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>review</option><option>manual_reissue</option><option>completed</option><option>rejected</option></select><input name="admin_note" placeholder="Note"><button>Update</button></form><?php else:?>Read only<?php endif;?></td></tr><?php endforeach;?></table></div></div></body></html>